INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-nikakawarazu-1', 'sent-ex-nikakawarazu-1', 'en', 'Regardless of the weather, the match will go ahead.', 'authored'),
  ('st-ex-nikakawarazu-2', 'sent-ex-nikakawarazu-2', 'en', 'Whatever the result, we will see it through to the end.', 'authored'),
  ('st-ex-nikakawarazu-3', 'sent-ex-nikakawarazu-3', 'en', 'Whatever the day, the shop is open.', 'authored'),
  ('st-ex-nikakawarazu-4', 'sent-ex-nikakawarazu-4', 'en', 'Price aside, we choose on quality.', 'authored'),
  ('st-ex-nimokakawarazu-1', 'sent-ex-nimokakawarazu-1', 'en', 'Despite the rain, a lot of people gathered.', 'authored'),
  ('st-ex-nimokakawarazu-2', 'sent-ex-nimokakawarazu-2', 'en', 'Despite my efforts, I failed.', 'authored'),
  ('st-ex-nimokakawarazu-3', 'sent-ex-nimokakawarazu-3', 'en', 'Young though he is, his experience is considerable.', 'authored'),
  ('st-ex-nimokakawarazu-4', 'sent-ex-nimokakawarazu-4', 'en', 'Busy as he was, he came.', 'authored'),
  ('st-ex-wotowazu-1', 'sent-ex-wotowazu-1', 'en', 'Anyone can take part, whatever their age.', 'authored'),
  ('st-ex-wotowazu-2', 'sent-ex-wotowazu-2', 'en', 'We are recruiting regardless of experience.', 'authored'),
  ('st-ex-wotowazu-3', 'sent-ex-wotowazu-3', 'en', 'It is popular whatever the season.', 'authored'),
  ('st-ex-wotowazu-4', 'sent-ex-wotowazu-4', 'en', 'You can use it at any hour.', 'authored'),
  ('st-ex-niwataru-1', 'sent-ex-niwataru-1', 'en', 'We talked it over for a long time.', 'authored'),
  ('st-ex-niwataru-2', 'sent-ex-niwataru-2', 'en', 'It rained right across the country.', 'authored'),
  ('st-ex-niwataru-3', 'sent-ex-niwataru-3', 'en', 'We surveyed a wide area.', 'authored'),
  ('st-ex-niwataru-4', 'sent-ex-niwataru-4', 'en', 'The roadworks went on over a long period.', 'authored'),
  ('st-ex-kawakiri-1', 'sent-ex-kawakiri-1', 'en', 'Starting with Japan, we will present it around the world.', 'authored'),
  ('st-ex-kawakiri-2', 'sent-ex-kawakiri-2', 'en', 'That film was the start of his popularity.', 'authored'),
  ('st-ex-kawakiri-3', 'sent-ex-kawakiri-3', 'en', 'Beginning with this meeting, the discussion got under way.', 'authored'),
  ('st-ex-kawakiri-4', 'sent-ex-kawakiri-4', 'en', 'Starting from that shop, it spread across the country.', 'authored'),
  ('st-ex-wokomete-1', 'sent-ex-wokomete-1', 'en', 'I made it with all my heart.', 'authored'),
  ('st-ex-wokomete-2', 'sent-ex-wokomete-2', 'en', 'I wrote the letter with gratitude.', 'authored'),
  ('st-ex-wokomete-3', 'sent-ex-wokomete-3', 'en', 'I sing it with love.', 'authored'),
  ('st-ex-wokomete-4', 'sent-ex-wokomete-4', 'en', 'I pushed with all my strength.', 'authored'),
  ('st-ex-womegutte-1', 'sent-ex-womegutte-1', 'en', 'The argument over that problem goes on.', 'authored'),
  ('st-ex-womegutte-2', 'sent-ex-womegutte-2', 'en', 'A dispute arose over the land.', 'authored'),
  ('st-ex-womegutte-3', 'sent-ex-womegutte-3', 'en', 'Opinion was divided over the plan.', 'authored'),
  ('st-ex-womegutte-4', 'sent-ex-womegutte-4', 'en', 'An investigation was carried out into the accident.', 'authored'),
  ('st-ex-nimotozuite-1', 'sent-ex-nimotozuite-1', 'en', 'Please write it based on the facts.', 'authored'),
  ('st-ex-nimotozuite-2', 'sent-ex-nimotozuite-2', 'en', 'We deal with it in accordance with the rules.', 'authored'),
  ('st-ex-nimotozuite-3', 'sent-ex-nimotozuite-3', 'en', 'I speak from experience.', 'authored'),
  ('st-ex-nimotozuite-4', 'sent-ex-nimotozuite-4', 'en', 'I presented it on the basis of the survey.', 'authored'),
  ('st-ex-womotoni-1', 'sent-ex-womotoni-1', 'en', 'He wrote a novel based on fact.', 'authored'),
  ('st-ex-womotoni-2', 'sent-ex-womotoni-2', 'en', 'We drew up the plan from the material.', 'authored'),
  ('st-ex-womotoni-3', 'sent-ex-womotoni-3', 'en', 'I will explain on the basis of experience.', 'authored'),
  ('st-ex-womotoni-4', 'sent-ex-womotoni-4', 'en', 'I will report on the basis of the survey.', 'authored'),
  ('st-ex-nioujite-1', 'sent-ex-nioujite-1', 'en', 'Tax is set according to income.', 'authored'),
  ('st-ex-nioujite-2', 'sent-ex-nioujite-2', 'en', 'I will help as needed.', 'authored'),
  ('st-ex-nioujite-3', 'sent-ex-nioujite-3', 'en', 'The cooking changes with the season.', 'authored'),
  ('st-ex-nioujite-4', 'sent-ex-nioujite-4', 'en', 'The price varies according to age.', 'authored')
